package book

import "github.com/go-playground/validator/v10"

// Book represents a book in the bookstore.
type Book struct {
	ID    string `json:"id"`
	Title  string `json:"title"`
	Author string `json:"author"`
	Pages  int    `json:"pages"`
}

// CreateBookRequest represents the request body for creating a new book.
type CreateBookRequest struct {
	Title  string `json:"title" validate:"required,min=3"`
	Author string `json:"author" validate:"required,min=3"`
	Pages  int    `json:"pages" validate:"required,min=1"`
}

// Validate validates the CreateBookRequest.
func (c *CreateBookRequest) Validate() error {
	validate := validator.New()
	return validate.Struct(c)
}

package store

import (
	"fmt"
	"sync"

	"bookstore-api/internal/book"
)

// BookStore defines the interface for book storage operations.
type BookStore interface {
	ListBooks() []book.Book
	GetBook(id string) (book.Book, error)
	CreateBook(book book.Book) error
}

// MemBookStore is an in-memory implementation of BookStore.
type MemBookStore struct {
	mu    sync.RWMutex
	books map[string]book.Book
}

// NewMemBookStore creates a new in-memory book store.
func NewMemBookStore() *MemBookStore {
	return &MemBookStore{
		books: make(map[string]book.Book),
	}
}

// ListBooks returns all books in the store.
func (s *MemBookStore) ListBooks() []book.Book {
	s.mu.RLock()
	defer s.mu.RUnlock()

	books := make([]book.Book, 0, len(s.books))
	for _, b := range s.books {
		books = append(books, b)
	}
	return books
}

// GetBook returns a book by its ID.
func (s *MemBookStore) GetBook(id string) (book.Book, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	b, ok := s.books[id]
	if !ok {
		return book.Book{}, fmt.Errorf("book with ID %s not found", id)
	}
	return b, nil
}

// CreateBook adds a new book to the store.
func (s *MemBookStore) CreateBook(b book.Book) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.books[b.ID]; ok {
		return fmt.Errorf("book with ID %s already exists", b.ID)
	}
	s.books[b.ID] = b
	return nil
}

package handlers

import (
	"encoding/json"
	"fmt"
	"net/http"

	"bookstore-api/internal/book"
	"bookstore-api/internal/store"

	"github.com/go-chi/chi/v5"
	"github.com/go-playground/validator/v10"
	"github.com/google/uuid"
)

// Handler holds the dependencies for our HTTP handlers.
type Handler struct {
	BookStore *store.MemBookStore
	Validator *validator.Validate
}

// NewHandler creates a new Handler instance.
func NewHandler(bookStore *store.MemBookStore) *Handler {
	return &Handler{
		BookStore: bookStore,
		Validator: validator.New(),
	}
}

// ListBooks returns a list of all books.
func (h *Handler) ListBooks(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	books := h.BookStore.ListBooks()

	if err := json.NewEncoder(w).Encode(books); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
}

// CreateBook creates a new book.
func (h *Handler) CreateBook(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	var req book.CreateBookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request payload", http.StatusBadRequest)
		return
	}

	if err := h.Validator.Struct(req); err != nil {
		// This handles validation errors from the 'validate' tags in the struct
		http.Error(w, fmt.Sprintf("Validation error: %v", err), http.StatusBadRequest)
		return
	}

	bookID := uuid.New().String()
	newBook := book.Book{
		ID:    bookID,
		Title:  req.Title,
		Author: req.Author,
		Pages:  req.Pages,
	}

	if err := h.BookStore.CreateBook(newBook); err != nil {
		http.Error(w, "Failed to create book", http.StatusInternalServerError)
		return	
	}

	w.WriteHeader(http.StatusCreated)
	if err := json.NewEncoder(w).Encode(newBook); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
}

// GetBook returns a single book by ID.
func (h *Handler) GetBook(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	id := chi.URLParam(r, "id")

	b, err := h.BookStore.GetBook(id)
	if err != nil {
		http.Error(w, "Book not found", http.StatusNotFound)
		return
	}

	if err := json.NewEncoder(w).Encode(b); err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
}

package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"bookstore-api/internal/handlers"
	"bookstore-api/internal/store"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

func main() {
	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer cancel()

	if err := run(ctx); err != nil {
		log.Printf("server terminated: %v", err)
		os.Exit(1)
	}
	log.Println("server gracefully stopped")
}

func run(ctx context.Context) error {
	bookStore := store.NewMemBookStore()
	handler := handlers.NewHandler(bookStore)

	r := chi.NewRouter()

	r.Use(middleware.RequestID)
	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)
	r.Use(middleware.Timeout(60 * time.Second))

	r.Get("/books", handler.ListBooks)
	r.Post("/books", handler.CreateBook)
	r.Get("/books/{id}", handler.GetBook)

	server := &http.Server{
		Addr:    ":8080",
		Handler: r,
	}

	go func() {
		<-ctx.Done()
		shutdownCtx, cancelShutdown := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancelShutdown()

		if err := server.Shutdown(shutdownCtx); err != nil {
			log.Printf("server shutdown failed: %v", err)
		}
	}()

	log.Printf("server listening on %s", server.Addr)
	return server.ListenAndServe()
}
